import React from "react";
import { Link } from "react-router-dom";
import { useCart } from "../context/CartContext";

const ProductCard = ({ product }) => {
  const { addToCart } = useCart();

  return (
    <div
      style={{
        background: "#fff",
        padding: "15px",
        borderRadius: "18px",
        boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
        textAlign: "center",
        transition: "0.3s",
        width: "100%", // important for grid
      }}
      onMouseOver={(e) =>
        (e.currentTarget.style.transform = "translateY(-6px) scale(1.02)")
      }
      onMouseOut={(e) =>
        (e.currentTarget.style.transform = "translateY(0) scale(1)")
      }
    >
      {/* IMAGE */}
      <div style={{ overflow: "hidden", borderRadius: "12px" }}>
        <img
          src={product.image}
          alt={product.name}
          style={{
            width: "100%",
            height: "200px",
            objectFit: "cover",
            transition: "0.3s",
          }}
        />
      </div>

      {/* NAME */}
      <h3
        style={{
          margin: "10px 0 5px",
          color: "#333",
          fontSize: "18px",
        }}
      >
        {product.name}
      </h3>

      {/* PRICE */}
      <p
        style={{
          color: "#d63384",
          fontWeight: "600",
          marginBottom: "5px",
        }}
      >
        ₹{product.price}
      </p>

      {/* AGE */}
      {product.age && (
        <p style={{ fontSize: "13px", color: "#777" }}>
          Age: {product.age}
        </p>
      )}

      {/* BUTTONS */}
      <button
        onClick={() => addToCart(product)}
        style={{
          marginTop: "10px",
          padding: "8px",
          border: "none",
          borderRadius: "15px",
          background: "#ff85a2",
          color: "#fff",
          cursor: "pointer",
          width: "100%",
          fontSize: "14px",
        }}
      >
        Add to Cart
      </button>

      <Link to={`/product/${product.id}`} style={{ textDecoration: "none" }}>
        <button
          style={{
            marginTop: "6px",
            padding: "7px",
            borderRadius: "15px",
            border: "1px solid #ff85a2",
            background: "#fff",
            color: "#ff4f87",
            cursor: "pointer",
            width: "100%",
            fontSize: "13px",
          }}
        >
          View Details
        </button>
      </Link>
    </div>
  );
};

export default ProductCard;
